/**
 * A class groups a teacher and their students. Its document id doubles as
 * the class code students type to join, so it is short, readable, and
 * generated by `createClassCode()` rather than by Firestore's auto-id.
 *
 * Membership is not stored here: it lives in the `enrollments` collection,
 * so a class document never has to be rewritten when a student joins or
 * leaves, and so Security Rules can check membership with a single
 * `exists()` on a deterministic document id.
 */
export interface Class {
  id: string
  name: string
  description: string
  teacherId: string
  /**
   * The teacher's name, copied at creation time. Students may read a class
   * they are enrolled in but not the teacher's `users` document, so the
   * name has to travel with the class.
   */
  teacherName: string
  createdAt: string
  updatedAt: string
}
